"use client"
import { useEffect, useState } from 'react';
import Nav from './Nav';
import Link from 'next/link';
import Image from 'next/image';
import { usePathname } from 'next/navigation';

export default function Header1({ variant } : any ) {
  const [mobileToggle, setMobileToggle] = useState(false);
  const [isSticky, setIsSticky] = useState<string>("");
  const [prevScrollPos, setPrevScrollPos] = useState<number>(0);
  const [searchToggle, setSearchToggle] = useState(false);
  const pathname = usePathname();
  
  // Check if current page is contact page
  const isContactPage = pathname === '/contact' || pathname === '/contact/';

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollPos = window.scrollY;
      if (currentScrollPos > prevScrollPos) {
        setIsSticky('cs-gescout_sticky'); // Scrolling down
      } else if (currentScrollPos !== 0) {
        setIsSticky('cs-gescout_show cs-gescout_sticky'); // Scrolling up
      } else {
        setIsSticky('');
      }
      setPrevScrollPos(currentScrollPos); // Update previous scroll position
    };

    window.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('scroll', handleScroll); // Cleanup the event listener
    };
  }, [prevScrollPos]);

  return (
    <div className="header-wrapper">
      {/* Top header navbar - ensure it's not hidden */}
      <div className="header-top-section" style={{ display: 'block', visibility: 'visible' }}>
        <div className="container-fluid">
          <div className="header-top-wrapper">
            <div className="top-left">
              <ul>
                <li><i className="bi bi-envelope"></i> info@example.com</li>
                <li><i className="bi bi-telephone"></i> +44 123 456 7890</li>
              </ul>
            </div>
            <div className="top-right">
              <ul>
                <li><Link href="/faq">FAQ</Link></li>
                <li>
                  <div className="social-icon">
                    <a href="#"><i className="bi bi-facebook"></i></a>
                    <a href="#"><i className="bi bi-twitter"></i></a>
                    <a href="#"><i className="bi bi-instagram"></i></a>
                  </div>
                </li>
              </ul>
            </div>
          </div>
        </div>
      </div>
      
      {/* Main header */}
      <header
        className={`cs_site_header header_style_2 header_style_2_0 cs_style_1 header_sticky_style1 ${
          variant ? variant : ''
        } cs_sticky_header cs_site_header_full_width ${
          mobileToggle ? 'cs_mobile_toggle_active' : ''
        } ${isSticky ? isSticky : ''} ${isContactPage ? 'contact-header' : ''}`}
      >
        <div className="cs_main_header">
          <div className="container-fluid">
            <div className="cs_main_header_in">
              <div className="cs_main_header_left">
                <Link className="cs_site_branding" href="/">
                  <Image src="/assets/img/logo/Logo666x172.svg" alt="img" width={213} height={55} />
                </Link>
              </div>
              <div className="cs_main_header_center">
                <div className={`cs_nav cs_primary_font fw-medium ${isContactPage ? 'contact-nav' : ''}`}>
                  <span
                    className={
                      mobileToggle
                        ? 'cs-munu_toggle cs_teggle_active'
                        : 'cs-munu_toggle'
                    }
                    onClick={() => setMobileToggle(!mobileToggle)}
                  >
                    <span></span>
                  </span>
                  <Nav setMobileToggle={setMobileToggle} />
                </div>
              </div>
              {/* Optional: Add header right section with buttons if needed */}
              <div className="cs_main_header_right">
                <div className="header-btn d-flex align-items-center">
                  <div className="main-button header-btn-1">
                    <a onClick={() => setSearchToggle(!searchToggle)} className="search-trigger search-icon">
                      <i className="bi bi-search"></i>
                    </a>
                    <Link href="/contact" className='theme-btn'>
                      <span>Request A Quote <i className="bi bi-arrow-right"></i></span>
                    </Link>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* ...existing search code... */}
      <div className={`search-wrap ${searchToggle ? 'active' : ''}`}>
        <div className="search-inner">
          <i onClick={() => setSearchToggle(!searchToggle)} id="search-close" className="bi bi-x-lg search-close"></i>
          <div className="search-cell">
            <form method="get">
              <div className="search-field-holder">
                <input type="search" className="main-search-input" placeholder="Search..." />
              </div>
            </form>
          </div>
        </div>
      </div>

      {/* ...existing styles... */}
      <style jsx global>{`
        /* Top header styles - ensure it's visible */
        .header-wrapper {
          position: relative;
          z-index: 999; /* Ensure it's above other elements */
        }
        
        .header-top-section {
          background-color: var(--theme);
          padding: 12px 0;
          position: relative;
          display: block !important;
          visibility: visible !important;
          z-index: 1000;
        }
        
        .header-top-wrapper {
          display: flex;
          align-items: center;
          justify-content: space-between;
        }
        
        .top-left, .top-right {
          display: flex;
          align-items: center;
        }
        
        .top-left ul, .top-right ul {
          display: flex;
          align-items: center;
          margin: 0;
          padding: 0;
          list-style: none;
        }
        
        .top-left li, .top-right li {
          color: var(--white);
          font-size: 14px;
          margin-right: 20px;
        }
        
        .top-left li i, .top-right li i {
          margin-right: 8px;
        }
        
        .top-right .social-icon {
          display: flex;
          align-items: center;
          gap: 10px;
        }
        
        .top-right .social-icon a {
          color: var(--white);
          font-size: 16px;
        }
        
        .top-right .social-icon a:hover {
          opacity: 0.8;
        }
        
        /* For contact page specific styling */
        .contact-header .header-top-section {
          background-color: #113D48;
        }
        
        /* Existing header styles */
        .contact-header .cs_nav .cs_nav_list > li > a {
          color: #000 !important;
        }
        
        .contact-header .cs_nav .cs_nav_list > li > a:hover {
          color: #000 !important;
        }

        .contact-nav .cs_nav_list .submenu li a {
          color: var(--header) !important;
        }

        .contact-header.cs-gescout_sticky .cs_nav .cs_nav_list > li > a {
          color: #000 !important;
        }
        
        /* Make top header responsive */
        @media (max-width: 767px) {
          .header-top-wrapper {
            flex-direction: column;
            gap: 10px;
          }
          
          .top-left ul, .top-right ul {
            flex-wrap: wrap;
            justify-content: center;
          }
          
          .top-left li, .top-right li {
            margin-right: 15px;
            margin-bottom: 5px;
            font-size: 12px;
          }
        }
      `}</style>
    </div>
  );
}
